文件：Tags.jsx
上下文：React 客户端组件；点击按钮应立即显示新增标签，组件不在表单内。
代码：
```jsx
import { useState } from 'react';
export function Tags() {
  const [tags, setTags] = useState([]);
  function addTag() {
    setTags(previous => [...previous, '新标签']);
  }
  return <div><button onClick={addTag}>添加</button><p>{tags.join(',')}</p></div>;
